-- ============================================================
-- SEED EXT 3: Módulo 07 — Present Perfect (ex 119-215)
-- Novos tópicos: PP vs Simple Past avançado, PP em pesquisa
-- acadêmica, passive PP, PP continuous vs PP, TOEFL integrado
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'present-perfect';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo present-perfect não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 31: PP vs Simple Past — discriminação avançada
  (cid,31,119,'multiple_choice','Why is past simple (not present perfect) correct in: "Einstein published his theory of special relativity in 1905"?','The event occurred at a specific past time (1905), and Einstein is no longer alive — no connection to now.','["Einstein is famous, so present perfect applies","The event occurred at a specific past time (1905), and Einstein is no longer alive — no connection to now.","Published is irregular so simple past is required","Past simple is always used with scientists"]','Specific past time reference (1905) = past simple. No current relevance implied.','hard'),
  (cid,31,120,'gap_fill','Scientists _____ (identify) over 1,000 new species in the last decade. (ongoing period with present relevance)','have identified',NULL,'"In the last decade" = period up to now = present perfect.','medium'),
  (cid,31,121,'multiple_choice','Which sentence uses tense INCORRECTLY?','The team has discovered a new element in 2023.','["The team discovered a new element in 2023 (past simple — specific year correct).","The team has discovered several new elements over the past decade (PP — ongoing period correct).","The team made a groundbreaking discovery last year (past simple — specific time marker correct).","The team has discovered a new element in 2023."]','"In 2023" = specific past time marker → past simple required, not present perfect.','hard'),
  (cid,31,122,'gap_fill','The pandemic _____ (expose) the fragility of global supply chains. (effect still felt now — no time marker)','has exposed',NULL,'No specific past time + current relevance = present perfect.','easy'),
  (cid,31,123,'multiple_choice','Which is correct in a TOEFL essay discussing recent events?','Research has shown that social isolation significantly affects mental health.','["Research showed that social isolation affects mental health (wrong — suggests this research is over/specific time).","Research shows that social isolation significantly affects mental health (present simple — also acceptable for established knowledge).","Research has shown that social isolation significantly affects mental health.","Research had shown that social isolation affects mental health."]','"Has shown" = recent research with current relevance. Standard in academic literature reviews.','medium'),
  (cid,31,124,'gap_fill','Several studies _____ (emerge) since 2018 challenging the dominant theory of cognitive development.','have emerged',NULL,'"Since 2018" + period up to now = present perfect.','easy'),

  -- BLOCK 32: PP passive em textos acadêmicos
  (cid,32,125,'gap_fill','The drug _____ (test/passive + PP) in three separate clinical trials and has shown consistent results.','has been tested',NULL,'"Has been + past participle" = present perfect passive.','medium'),
  (cid,32,126,'multiple_choice','Which sentence uses present perfect passive correctly?','The relationship between diet and cancer risk has been studied extensively over the past 30 years.','["The relationship between diet and cancer risk was studied extensively over the past 30 years (past — specific period now closed).","The relationship between diet and cancer risk has studied extensively for 30 years (missing been).","The relationship between diet and cancer risk has been studied extensively over the past 30 years.","The relationship between diet and cancer risk has been studying extensively."]','"Has been + past participle" = PP passive for research over an ongoing period.','medium'),
  (cid,32,127,'gap_fill','The model _____ (validate/passive + PP) by an independent research team, which lends further credibility to the findings.','has been validated',NULL,'"Has been validated" = PP passive. Present relevance (it IS now credible).','medium'),
  (cid,32,128,'multiple_choice','Why does academic writing frequently use present perfect passive?','To report completed research actions whose results are still relevant, while keeping an impersonal/formal tone.','["To avoid using subject pronouns","To make sentences longer","To report completed research actions whose results are still relevant, while keeping an impersonal/formal tone.","Present perfect is required in academic writing"]','PP passive = combines recency/relevance with the formality and objectivity of passive voice.','hard'),
  (cid,32,129,'gap_fill','The procedure _____ (refine/passive + PP) significantly since its initial development in the 1980s.','has been refined',NULL,'"Has been refined since" = PP passive with "since" marker.','medium'),

  -- BLOCK 33: PP continuous vs PP — nuances avançadas
  (cid,33,130,'multiple_choice','Which is more appropriate? "She _____ on the paper for six months" when the paper is now complete.','has worked','["has been working (emphasizes the process, implies still ongoing or just finished)","has worked (completed, duration mentioned, result implied)","worked (past simple — if there''s a specific time like ''last semester'')","has been worked (passive — wrong)"]','Both possible; "has worked" (result/completion) is slightly more natural when the outcome is mentioned.','hard'),
  (cid,33,131,'gap_fill','The temperature _____ (rise/PP continuous) steadily since the 1950s, according to climate records.','has been rising',NULL,'"Has been rising" = PP continuous for a gradual ongoing process.','medium'),
  (cid,33,132,'multiple_choice','What nuance does "has been investigating" add vs "has investigated"?','Has been investigating = process/duration emphasized (still may be ongoing). Has investigated = result/completion.','["They are identical","Has been investigating = passive","Has been investigating = process/duration emphasized (still may be ongoing). Has investigated = result/completion.","Has been investigating is informal"]','PP continuous = process/duration. PP simple = result.','hard'),
  (cid,33,133,'gap_fill','The economy _____ (contract/PP continuous) for three consecutive quarters, raising fears of a prolonged recession.','has been contracting',NULL,'Ongoing economic process = PP continuous.','medium'),
  (cid,33,134,'multiple_choice','In: "The committee has reviewed the application and has decided to approve it," why is present perfect used for both verbs?','Both actions are recent and have current relevance — the decision is now in effect.','["Both verbs are irregular","Both actions are recent and have current relevance — the decision is now in effect.","Past simple would also be correct but is less formal","Present perfect is always used after committee"]','Two recent actions with immediate present consequences = PP for both.','medium'),

  -- BLOCK 34: PP com advérbios de frequência e resultado
  (cid,34,135,'gap_fill','She has _____ (never/visit) the research site in person, having conducted all her analysis remotely.','never visited',NULL,'"Has never + past participle" = present perfect with frequency adverb.','easy'),
  (cid,34,136,'multiple_choice','Which adverb CANNOT typically modify a present perfect verb?','Yesterday','["Already","Yet","Since","Yesterday"]','"Yesterday" = specific past time → requires past simple. Already/yet/since go with present perfect.','medium'),
  (cid,34,137,'gap_fill','The results _____ (already / confirm/passive) three times, so there is no need for further replication.','have already been confirmed',NULL,'"Have already been confirmed" = PP passive + already.','hard'),
  (cid,34,138,'multiple_choice','In "She has just submitted her thesis," "just" indicates:','A very recent action with immediate present relevance.','["An action in a distant past","An action planned for the future","A very recent action with immediate present relevance.","A repeated action"]','"Has just + past participle" = very recent completion.','easy'),
  (cid,34,139,'gap_fill','The committee has _____ (yet/decide) whether to extend the research grant. (negative — not yet decided)','not yet decided',NULL,'"Has not yet + past participle" = expected action that hasn''t happened.','easy'),

  -- BLOCK 35: TOEFL Reading
  (cid,35,140,'multiple_choice','[TOEFL Reading] "Scientists have long debated whether dark matter exists in discrete particles or as a diffuse field." "Have long debated" indicates:','The debate has been ongoing for a long time and continues to the present.','["The debate ended recently","The debate has been ongoing for a long time and continues to the present.","Scientists debated once and agreed","The debate has been resolved"]','"Have + long + past participle" = present perfect with duration marker indicating extended ongoing relevance.','medium'),
  (cid,35,141,'gap_fill','[TOEFL Reading] "Researchers _____ (discover + PP passive) that certain gut bacteria may influence mood through the gut-brain axis." Best form?','have discovered',NULL,'"Have discovered" = recent research with present relevance (no specific past time).','easy'),
  (cid,35,142,'multiple_choice','[TOEFL Reading] "The depletion of ozone in the stratosphere has accelerated since the 1970s." Why present perfect + "since"?','The process began in the 1970s and is still ongoing, with relevance to the current situation.','["Ozone depletion is now complete","The 1970s is a specific point initiating a still-ongoing process, so present perfect + since.","Since always requires past simple","Past simple should be used because a decade is mentioned"]','"Since the 1970s" + ongoing process = present perfect.','medium'),
  (cid,35,143,'gap_fill','[TOEFL Reading] "The population of tigers _____ (decline + PP) by over 90% in the last century." Best form?','has declined',NULL,'"In the last century" = period up to now = present perfect.','easy'),
  (cid,35,144,'multiple_choice','[TOEFL Reading] "Darwin observed finches during his voyage to the Galápagos." Why past simple (not present perfect)?','A specific past event at a specific time (the Galápagos voyage) — not an ongoing phenomenon.','["Darwin is famous","Finches is plural","A specific past event at a specific time (the Galápagos voyage) — not an ongoing phenomenon.","Observed is a stative verb"]','Specific historical event + implied time reference = past simple.','easy'),

  -- BLOCK 36: TOEFL Speaking
  (cid,36,145,'production','[TOEFL Speaking — 45s] A reading says international cooperation has made the world safer since 1945. Agree or disagree. Use: has/have + PP (at least 3), has been + -ing (PP continuous), passive PP.','',NULL,'International institutions have achieved significant milestones since 1945 — the rate of interstate wars has declined dramatically, and frameworks for trade and human rights have been established that simply did not exist before. Diplomats have been working for decades to manage conflicts through dialogue rather than force. Smallpox has been eradicated, and polio has been nearly eliminated through coordinated global health campaigns. However, recent evidence suggests that multilateral cooperation has been weakening, as nationalism has risen and great power competition has intensified. The question is not whether cooperation has worked, but whether it will continue to work.','hard'),
  (cid,36,146,'production','[TOEFL Speaking — 45s] A professor discusses how AI has changed the job market. Summarize and give your opinion. Use PP, PP passive, and PP continuous.','',NULL,'According to the professor, artificial intelligence has transformed the job market in ways both positive and negative. Many repetitive jobs have been displaced by automation, while new roles in AI development and oversight have been created. Research into the net employment effects has been ongoing for several years, but a definitive consensus has not yet emerged. I believe that while AI has eliminated some low-skill positions, it has also been raising productivity in knowledge-intensive sectors, and with proper investment in retraining, the transition can be managed effectively.','hard'),

  -- BLOCK 37: TOEFL Writing
  (cid,37,147,'production','[TOEFL Writing — 150 words] Write an academic paragraph on "How has the Internet changed education?" Use: PP (at least 4), PP passive (at least 2), PP continuous (at least 1), and contrast with past simple for completed historical events.','',NULL,'The Internet has fundamentally reshaped the landscape of education over the past three decades. When the first major online learning platforms were launched in the 2000s, skeptics argued that digital tools would supplement rather than transform teaching. Since then, however, the field has evolved dramatically. Millions of learners have been enrolled in online courses, and hundreds of thousands of educational resources have been made freely available to anyone with Internet access. Platforms such as Coursera and Khan Academy have democratized access to high-quality instruction in ways that physical institutions have struggled to match. Inequalities in digital access have been documented extensively, highlighting the risk that technological progress may widen rather than narrow educational gaps. Researchers have been investigating these disparities, and several policy frameworks have been proposed to ensure that the benefits of digital education are equitably distributed.','hard'),
  (cid,37,148,'production','[TOEFL Writing — Error Correction] Fix all present perfect errors: "Scientists discovered that the comet has passed near Earth last year. The ozone layer has been depleted for the first time in 1985. She has already submitted the paper yesterday. The committee has meet three times since January."','',NULL,'has passed → passed (specific past time "last year" → past simple); has been depleted for the first time → was first depleted (specific event in the past, "in 1985" = past simple); has already submitted + yesterday → already submitted yesterday / submitted the paper yesterday (past time adverb = past simple); has meet → has met (irregular past participle of meet = met).','hard'),
  (cid,37,149,'production','[TOEFL Writing — 200 words] Write a TOEFL essay paragraph on "The effects of globalization on cultural identity." Use a minimum of 6 present perfect forms (including PP passive and PP continuous), contrast with at least 2 past simples, and include hedging language.','',NULL,'Globalization has dramatically reshaped cultural identities around the world, raising questions about the extent to which local traditions can survive in an era of unprecedented interconnection. Critics have argued for decades that the global spread of Western consumer culture has eroded the diversity of local customs and languages. Indeed, UNESCO reported in 2010 that hundreds of indigenous languages had already disappeared since the mid-20th century, and this process of linguistic attrition has continued. At the same time, new hybrid forms of cultural expression have emerged, blending global influences with local traditions in ways that have enriched rather than diminished cultural life. The internet has been facilitating cross-cultural exchange at a scale that earlier generations could not have imagined. The evidence suggests that the effects of globalization on culture are complex and context-dependent: communities that have maintained strong institutional support for local languages and arts appear to have fared considerably better than those left without such support. Further research is needed before definitive conclusions can be drawn.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
